class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def level_order(root):
    levels = []
    current = [root] if root is not None else []
    while current:
        levels.append([node.val for node in current])
        # the next level: every child of this level, left before right, skipping missing ones
        current = [child for node in current for child in (node.left, node.right) if child is not None]
    return levels
